height, width = 25, 13

def transform_v2(input_grid):
    """Each 8 becomes pattern 2-1-6 centered at the 8's position."""
    output = [row[:] for row in input_grid]

    for r in range(height):
        for c in range(width):
            if input_grid[r][c] == 8:
