def transform(grid):
    """Replace all 8s with horizontal 2-1-6 patterns.
    The pattern is centered at the 8's position: 2 at left, 1 at center, 6 at right."""
    height = len(grid)
    width = len(grid[0]) if grid else 0

    # Copy input grid
    output = [row[:] for row in grid]

    # Replace all 8s
    for r in range(height):
        for c in range(width):
            if output[r][c] == 8:
                output[r][c] = 1        # center
                if c - 1 >= 0:
                    output[r][c-1] = 2  # left
                if c + 1 < width:
                    output[r][c+1] = 6  # right

    return output

